"""Persistent decision history with point-in-time replay."""

from __future__ import annotations

import copy
import json
import os
import tempfile
from typing import Any

from .policy import _check_non_empty_str, _check_time, _select_matched, _snapshot_basis, _validate_rules

_RECORD_KEYS = frozenset({"id", "at", "decision", "trace", "basis"})
_BASIS_KEYS = ("id", "ver", "source", "priority", "from", "to", "when", "result")


class DecisionHistory:
    """Append decision records to a compact UTF-8 JSON file and replay them.

    The file always holds ``{"records": [...]}`` sorted by ``(id, at)``
    Unicode code point order, serialized without ASCII escaping or extra
    whitespace and terminated by a single trailing newline.
    """

    def __init__(self, path: str):
        _check_non_empty_str(path, "path")
        self.path = path
        self._records: list[dict[str, Any]] = self._load()

    def _load(self) -> list[dict[str, Any]]:
        try:
            with open(self.path, encoding="utf-8") as handle:
                text = handle.read()
        except FileNotFoundError:
            return []
        except OSError:
            raise
        try:
            data = json.loads(text)
        except (json.JSONDecodeError, UnicodeDecodeError) as exc:
            raise ValueError(f"history file is not valid JSON: {self.path!r}") from exc
        records = self._validate_document(data)
        records.sort(key=lambda record: (record["id"], record["at"]))
        return records

    def _validate_document(self, data: Any) -> list[dict[str, Any]]:
        if not isinstance(data, dict) or set(data) != {"records"}:
            raise ValueError("history document must be an object with exactly the key 'records'")
        records = data["records"]
        if not isinstance(records, list):
            raise ValueError("history 'records' must be a list")
        seen: set[tuple[str, str]] = set()
        for index, record in enumerate(records):
            field = f"records[{index}]"
            if not isinstance(record, dict) or set(record) != _RECORD_KEYS:
                raise ValueError(
                    f"{field} must be a dict with exactly the keys "
                    "id, at, decision, trace, basis"
                )
            _check_non_empty_str(record["id"], f"{field}.id")
            _check_time(record["at"], f"{field}.at")
            decision = record["decision"]
            if decision is not None:
                _check_non_empty_str(decision, f"{field}.decision")
            trace = record["trace"]
            if not isinstance(trace, list) or not all(
                isinstance(item, str) and "@" in item for item in trace
            ):
                raise ValueError(f"{field}.trace must be a list of 'id@ver' strings")
            key = (record["id"], record["at"])
            if key in seen:
                raise ValueError(f"duplicate record (id, at): {key!r}")
            seen.add(key)
            self._validate_basis(record["basis"], f"{field}.basis", decision, trace)
        return records

    def _validate_basis(
        self, basis: Any, field: str, decision: str | None, trace: list[str]
    ) -> None:
        if basis is None:
            if decision is not None or trace:
                raise ValueError(f"{field} must be present when decision/trace are non-null")
            return
        if decision is None:
            raise ValueError(f"{field} must be null when decision is null")
        if not isinstance(basis, dict) or tuple(basis) != _BASIS_KEYS:
            raise ValueError(
                f"{field} must be a dict with exactly the keys "
                "id, ver, source, priority, from, to, when, result in order"
            )
        if basis["result"] != decision:
            raise ValueError(f"{field}.result must equal decision")
        expected_head = f"{basis['id']}@{basis['ver']}"
        if not trace or trace[0] != expected_head:
            raise ValueError(f"{field} rule must be the head of trace")
        if not isinstance(basis["id"], str) or not basis["id"]:
            raise ValueError(f"{field}.id must be a non-empty string")
        if isinstance(basis["ver"], bool) or not isinstance(basis["ver"], int) or basis["ver"] < 1:
            raise ValueError(f"{field}.ver must be a positive integer")
        if basis["source"] not in ("law", "org"):
            raise ValueError(f"{field}.source must be 'law' or 'org'")
        if isinstance(basis["priority"], bool) or not isinstance(basis["priority"], int):
            raise ValueError(f"{field}.priority must be an integer")
        if isinstance(basis["result"], str) and not basis["result"]:
            raise ValueError(f"{field}.result must be a non-empty string")
        elif not isinstance(basis["result"], str):
            raise ValueError(f"{field}.result must be a string")
        _check_time(basis["from"], f"{field}.from")
        if basis["to"] is not None:
            _check_time(basis["to"], f"{field}.to")
            if not basis["from"] < basis["to"]:
                raise ValueError(f"{field} requires from < to")
        when = basis["when"]
        if when is not None:
            if not isinstance(when, dict) or any(not isinstance(k, str) or not k for k in when):
                raise ValueError(f"{field}.when keys must be non-empty strings")
            if any(not isinstance(v, bool) for v in when.values()):
                raise ValueError(f"{field}.when values must be bool")

    def _write(self) -> None:
        """Atomically replace the history file; the previous file survives a
        failed write."""
        directory = os.path.dirname(os.path.abspath(self.path))
        os.makedirs(directory, exist_ok=True)
        payload = json.dumps(
            {"records": self._records}, ensure_ascii=False, separators=(",", ":")
        )
        fd, tmp_name = tempfile.mkstemp(
            prefix=".history-", suffix=".tmp", dir=directory, text=True
        )
        try:
            with os.fdopen(fd, "w", encoding="utf-8", newline="") as handle:
                handle.write(payload)
                handle.write("\n")
                handle.flush()
                os.fsync(handle.fileno())
            os.replace(tmp_name, self.path)
        except OSError:
            try:
                os.unlink(tmp_name)
            except OSError:
                pass
            raise

    def record(
        self,
        record_id: str,
        at: str,
        facts: dict[str, bool],
        rules: list[dict[str, Any]],
    ) -> dict[str, Any]:
        """Evaluate ``rules`` against ``facts`` at ``at`` and persist the
        outcome under ``record_id``.

        Validation, version selection and ranking behave exactly like
        :func:`regulation_policy_compiler.policy.evaluate`. ``record_id`` must
        be a non-empty string and the ``(record_id, at)`` pair must be unique.
        Returns the stored record; with no matching rule it stores
        ``decision=None, trace=[], basis=None``, otherwise ``basis`` is an
        ordered snapshot of the winning rule.
        """
        _check_non_empty_str(record_id, "record_id")
        _check_time(at, "at")
        from .policy import _check_fact_map

        _check_fact_map(facts, "facts")
        rules = _validate_rules(rules)

        key = (record_id, at)
        if any((item["id"], item["at"]) == key for item in self._records):
            raise ValueError(f"duplicate record (id, at): {key!r}")

        matched = _select_matched(at, facts, rules)
        if matched:
            winner = matched[0]
            entry: dict[str, Any] = {
                "id": record_id,
                "at": at,
                "decision": winner["result"],
                "trace": [f"{rule['id']}@{rule['ver']}" for rule in matched],
                "basis": _snapshot_basis(winner),
            }
        else:
            entry = {"id": record_id, "at": at, "decision": None, "trace": [], "basis": None}

        self._records.append(entry)
        self._records.sort(key=lambda record: (record["id"], record["at"]))
        self._write()
        return copy.deepcopy(entry)

    def replay(self, record_id: str, at: str) -> dict[str, Any]:
        """Return a copy of the stored record for ``record_id`` whose ``at`` is
        the most recent one not later than ``at``.

        The decision is read from storage and never recomputed. Raises
        :class:`KeyError` when no such record exists.
        """
        _check_non_empty_str(record_id, "record_id")
        _check_time(at, "at")
        choice: dict[str, Any] | None = None
        for item in self._records:
            if item["id"] == record_id and item["at"] <= at:
                if choice is None or item["at"] > choice["at"]:
                    choice = item
        if choice is None:
            raise KeyError(f"no record for {record_id!r} at or before {at!r}")
        return copy.deepcopy(choice)

